const adhd=document.documentElement.dataset.product==='adhd';
const places=[['Zamek w Łańcucie',50.0686,22.2346,'Spacer po parku i chwila bez ekranu.'],['Zamek w Krasiczynie',49.7769,22.6522,'Renesansowy zamek i park nad Sanem.'],['Arboretum w Bolestraszycach',49.817,22.858,'Ogród na spokojną wyprawę. Sprawdź godziny otwarcia.'],['Rynek w Rzeszowie',50.037,22.004,'Krótki spacer i odkrywanie centrum.'],['Zamek w Przeworsku — park Lubomirskich',50.057,22.484,'Park i pałac Lubomirskich na spokojne popołudnie.'],['Muzeum Budownictwa Ludowego w Sanoku',49.571,22.205,'Dłuższa wycieczka do skansenu. Sprawdź bilety i godziny.']];
let chosen=Number(localStorage.getItem('escape-place')||0)%places.length,weather,loading=false;
const links=[['ATRIA','Twoje biuro. Twoja marka.','https://atria-nieruchomosci.pl/'],['ATRIA · Facebook','Pokaż ludziom, nad czym pracujesz.','https://www.facebook.com/profile.php?id=61594608104354'],['Otodom','Oferty i Twój rynek.','https://www.otodom.pl/'],['OLX · Nieruchomości','Sprawdź lokalne ogłoszenia.','https://www.olx.pl/nieruchomosci/']];
const style=document.createElement('style');style.textContent=`.life-links{margin:0 0 24px}.portal-logo{height:48px;width:100%;object-fit:contain;object-position:left center}.life-link{min-height:140px!important;background:#a9bbca!important;color:#17383b!important}.life-link strong{color:#17383b!important}.life-link small{color:#294458!important}.life-hub{margin:0 0 28px;display:grid;gap:16px}.life-top{display:grid;grid-template-columns:1.2fr 1fr;gap:16px}.life-card{border:1px solid #ffffff19;border-radius:24px;padding:22px;background:radial-gradient(ellipse at 100% 0,#b9dcd51c,transparent 70%),var(--panel,#20271f);box-shadow:0 12px 35px #0001}.life-label{font-size:9px;letter-spacing:.18em;text-transform:uppercase;color:var(--muted);margin-bottom:10px}.life-card h2{font-size:21px;margin:0 0 8px}.life-copy{font-size:12px;color:var(--muted);line-height:1.7}.life-weather{font-size:35px;letter-spacing:-.05em;margin:12px 0}.life-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}.life-links{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.life-link{display:block;color:inherit;text-decoration:none;padding:22px;border-radius:19px;border:1px solid #d9bd7933;background:linear-gradient(145deg,#d9bd7919,#1b261e);transition:transform .2s}.life-link:hover{transform:translateY(-3px)}.life-link strong{display:block;font-family:Georgia,serif;color:var(--gold);font-size:21px;margin:8px 0}.life-link small{font-size:10px;color:var(--muted)}.life-map{width:100%;height:290px;border:0;border-radius:15px;margin-top:16px;background:#27342e}.life-modal{max-width:510px}.life-modal label{display:grid;gap:7px;margin:14px 0;font-size:12px}.life-modal input{width:100%;padding:12px;border-radius:10px;background:#0003;color:inherit;border:1px solid #ffffff30}.life-note{font-size:11px;color:var(--muted);margin-top:12px}@media(max-width:650px){.life-top{grid-template-columns:1fr}.life-links{grid-template-columns:1fr 1fr}.life-card{padding:19px}.life-link{padding:17px}.life-map{height:240px}}`;document.head.append(style);
function mount(){const main=document.querySelector('main');if(!main||main.querySelector('.life-hub')||!['more','portals'].includes(main.dataset.view))return;const hub=document.createElement('section');hub.className='life-hub';hub.setAttribute('aria-label','Twój dzień i inspiracje');hub.innerHTML='<div class="life-top"><section class="life-card"><div class="life-label">ZA OKNEM · TWÓJ RYTM</div><h2>Pogoda na dziś</h2><div id="life-weather" aria-live="polite">Pobieram pogodę dla Łańcuta…</div><div class="life-actions"><button class="btn" data-life="weather">Odśwież</button><button class="btn" data-life="location">Moja lokalizacja</button></div><p class="life-note">Prognoza modelowa · <a href="https://open-meteo.com/" target="_blank" rel="noopener noreferrer">Open-Meteo</a></p></section><section class="life-card"><div class="life-label">MNIEJ W GŁOWIE · WIĘCEJ PRZESTRZENI</div><h2>Umów się ze sobą</h2><p class="life-copy">'+(adhd?'Zarezerwuj mały krok, spacer albo spokojne 15 minut.':'Zaplanuj telefon, prezentację albo blok akwizycji.')+'</p><div class="life-actions"><button class="btn" data-life="calendar">＋ Dodaj do Kalendarza Apple</button></div><p class="life-note">Plik .ics do importu. Wydarzenie dodajesz sam — bez automatycznej synchronizacji.</p></section></div>'+(adhd?'<section class="life-card"><div class="life-label">MAŁA WYPRAWA · PODKARPACIE</div><h2>Dokąd dziś?</h2><p class="life-copy">Nie musisz zasłużyć na odpoczynek. Wylosuj pomysł na wyjście.</p><div id="life-place"></div><div class="life-actions"><button class="btn" data-life="random">✧ Wylosuj inne miejsce</button></div><p class="life-note">Wybrane inspiracje turystyczne, nie lista aktualnie otwartych obiektów. Przed wyjazdem sprawdź dostępność.</p></section>':'<div class="life-links">'+links.map(([n,d,u],i)=>'<a class="life-link" href="'+u+'" target="_blank" rel="noopener noreferrer"><img class="portal-logo" src="'+["data:image/webp;base64,","data:image/png;base64,","data:image/svg+xml;base64,","data:image/png;base64,"][i]+'" alt="Logo '+n+'"><strong>'+n+'</strong><small>'+d+'</small></a>').join('')+'</div>');if(main.dataset.view==='portals')hub.querySelector('.life-top').remove();
else hub.querySelector('.life-links')?.remove();
main.append(hub);renderWeather();if(adhd)renderPlace();}
function renderPlace(){const root=document.getElementById('life-place');if(!root)return;const [name,lat,lon,desc]=places[chosen];root.replaceChildren();const title=document.createElement('h3');title.textContent=name;title.style.marginTop='20px';const p=document.createElement('p');p.className='life-copy';p.textContent=desc;const frame=document.createElement('iframe');frame.className='life-map';frame.title='OpenStreetMap: '+name;frame.loading='lazy';frame.referrerPolicy='strict-origin-when-cross-origin';frame.src='https://www.openstreetmap.org/export/embed.html?bbox='+[lon-.025,lat-.015,lon+.025,lat+.015].join('%2C')+'&layer=mapnik&marker='+lat+'%2C'+lon;const a=document.createElement('a');a.href='https://www.openstreetmap.org/?mlat='+lat+'&mlon='+lon+'#map=15/'+lat+'/'+lon;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Otwórz mapę · © OpenStreetMap contributors';root.append(title,p,frame,a);}
function renderWeather(){const el=document.getElementById('life-weather');if(!el||!weather)return;el.replaceChildren();const temp=document.createElement('div');temp.className='life-weather';temp.textContent=Math.round(weather.temperature)+'° '+weather.label;const text=document.createElement('p');text.className='life-copy';text.textContent=weather.name+' · wiatr '+Math.round(weather.wind)+' km/h · pomiar modelowy '+new Date(weather.time).toLocaleTimeString('pl-PL',{hour:'2-digit',minute:'2-digit'});el.append(temp,text);}
async function getWeather(lat=50.068,lon=22.23,name='Łańcut'){if(loading)return;loading=true;try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude='+lat+'&longitude='+lon+'&current=temperature_2m,weather_code,wind_speed_10m&timezone=auto',{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const j=await r.json(),c=j.current;if(!Number.isFinite(c.temperature_2m))throw Error();const code=c.weather_code;weather={temperature:c.temperature_2m,wind:c.wind_speed_10m,label:code===0?'☀️':code<4?'⛅':code<50?'🌫️':code<70?'🌧️':code<80?'❄️':'⛈️',name,time:c.time};renderWeather();}catch{const e=document.getElementById('life-weather');if(e)e.textContent='Pogoda chwilowo niedostępna. Spróbuj odświeżyć.';}finally{loading=false;}}
function calendar(){let d=document.getElementById('life-calendar');if(d)d.remove();d=document.createElement('dialog');d.id='life-calendar';d.className='life-modal';const tomorrow=new Date();tomorrow.setMinutes(tomorrow.getMinutes()-tomorrow.getTimezoneOffset());d.innerHTML='<h2>Twój następny krok</h2><form><label>Nazwa wydarzenia<input name="title" maxlength="160" required placeholder="Np. spacer albo prezentacja mieszkania"></label><label>Kiedy<input name="date" type="datetime-local" value="'+tomorrow.toISOString().slice(0,16)+'" required></label><label>Czas w minutach<input name="duration" type="number" value="30" min="5" max="1440" required></label><p class="life-copy">Otwórz lub zaimportuj plik w Kalendarzu Apple. Jeżeli iPhone pokaże tylko podgląd, udostępnij plik przez Mail i otwórz załącznik .ics.</p><div class="life-actions"><button class="btn" type="submit">Utwórz wydarzenie .ics</button><button class="btn" type="button" data-life="close-calendar">Zamknij</button></div></form>';d.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const data=new FormData(e.target),start=new Date(data.get('date')),end=new Date(start.getTime()+Number(data.get('duration'))*60000);const stamp=t=>t.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const esc=s=>String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Adrian Apps//Calendar//PL','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@adrian-apps','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(start),'DTEND:'+stamp(end),'SUMMARY:'+esc(data.get('title')),'END:VEVENT','END:VCALENDAR',''].join('\r\n');const file=new File([text],'wydarzenie.ics',{type:'text/calendar;charset=utf-8'});if(navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Dodaj do kalendarza'});return;}catch(err){if(err.name==='AbortError')return;}}const a=document.createElement('a'),url=URL.createObjectURL(file);a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);});document.body.append(d);d.showModal();}
document.addEventListener('click',e=>{const a=e.target.closest('[data-life]')?.dataset.life;if(a==='random'){chosen=(chosen+1+Math.floor(Math.random()*(places.length-1)))%places.length;localStorage.setItem('escape-place',String(chosen));renderPlace();}if(a==='weather')getWeather();if(a==='location'){if(!navigator.geolocation)return;navigator.geolocation.getCurrentPosition(p=>getWeather(p.coords.latitude,p.coords.longitude,'Twoja okolica'),()=>{const el=document.getElementById('life-weather');if(el)el.textContent='Lokalizacja niedostępna. Odśwież pogodę dla Łańcuta.';},{timeout:12000,maximumAge:600000});}if(a==='calendar')calendar();if(a==='close-calendar')document.getElementById('life-calendar')?.close();});
new MutationObserver(mount).observe(document.querySelector('main'),{childList:true});mount();getWeather();setInterval(()=>{if(!document.hidden)getWeather();},15*60*1000);
